NEED = {'POP': 1, 'DUP': 1, 'PRINT': 1, 'STORE': 1, 'JZ': 1, 'SWAP': 2, 'ADD': 2, 'SUB': 2, 'MUL': 2, 'DIV': 2, 'MOD': 2}
