stack, registers, out = [], {}, []
pc = steps = 0
while pc < len(program):
    if steps == LIMIT:
        out.append('timeout')
        break
    number, op, arg = program[pc]
    if (len(stack) < NEED.get(op, 0) or (op in ('JMP', 'JZ') and arg not in labels)
